INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mp3HEdorUDw', 4, '{"title":"第20202625条・至真要大论篇第七十四","description":"<p>150、少阴在泉。客胜则腰痛。尻股膝髀䯒足病。瞀热以酸。胕肿不能久立。溲便变。主胜则厥气上行。心痛发热。膈中。众痹皆作。发于胠胁。魄汗不藏。四逆而起。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202625,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '150、少阴在泉。客胜则腰痛。尻股膝髀䯒足病。瞀热以酸。胕肿不能久立。溲便变。主胜则厥气上行。心痛发热。膈中。众痹皆作。发于胠胁。魄汗不藏。四逆而起。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wICVptFJup0', 4, '{"title":"第20202626条・至真要大论篇第七十四","description":"<p>151、太阴在泉。客胜则足痿下重。便溲不时。湿客下焦。发而濡泻。及为肿隐曲之疾。主胜则寒气逆满。食饮不下。甚则为疝。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202626,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '151、太阴在泉。客胜则足痿下重。便溲不时。湿客下焦。发而濡泻。及为肿隐曲之疾。主胜则寒气逆满。食饮不下。甚则为疝。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
