INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bGPvcXrcogG', 4, '{"title":"第20202653条・至真要大论篇第七十四","description":"<p>178、大要曰：君一臣二。奇之制也。君二臣四。偶之制也。君二臣三。奇之制也。君二臣六。偶之制也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202653,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '178、大要曰：君一臣二。奇之制也。君二臣四。偶之制也。君二臣三。奇之制也。君二臣六。偶之制也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UvN6PDwUl83', 4, '{"title":"第20202654条・至真要大论篇第七十四","description":"<p>179、故曰：近者奇之。远者偶之。汗者不以奇。下者不以偶。补上治上制以缓。补下治下制以急。急则气味浓。缓则气味薄。适其至所。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202654,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '179、故曰：近者奇之。远者偶之。汗者不以奇。下者不以偶。补上治上制以缓。补下治下制以急。急则气味浓。缓则气味薄。适其至所。此之谓也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('70FvFif7v4N', 4, '{"title":"第20202655条・至真要大论篇第七十四","description":"<p>180、病所远而中道气味之者。食而过之。无越其制度也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202655,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '180、病所远而中道气味之者。食而过之。无越其制度也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n0UXhpvNisr', 4, '{"title":"第20202656条・至真要大论篇第七十四","description":"<p>181、是故平气之道。近而奇偶。制小其服也。远而奇偶。制大其服也。大则数少。小则数多。多则九之。少则二之。奇之不去则偶之。是谓重方。偶之不去。则反佐以取之。所谓寒热温凉。反从其病也。    帝曰：善。病生于本。余知之矣。生于标者。治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202656,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '181、是故平气之道。近而奇偶。制小其服也。远而奇偶。制大其服也。大则数少。小则数多。多则九之。少则二之。奇之不去则偶之。是谓重方。偶之不去。则反佐以取之。所谓寒热温凉。反从其病也。 帝曰：善。病生于本。余知之矣。生于标者。治之奈何？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ysAFgCD23KE', 4, '{"title":"第20202657条・至真要大论篇第七十四","description":"<p>182、岐伯曰：病反其本。中标之病。治反其本。中标之方。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202657,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '182、岐伯曰：病反其本。中标之病。治反其本。中标之方。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CXOZ2XRQIQh', 4, '{"title":"第20202658条・至真要大论篇第七十四","description":"<p>183、帝曰：善。六气之胜。何以候之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202658,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '183、帝曰：善。六气之胜。何以候之？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
