INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IF20hIzfly5', 4, '{"title":"第20202663条・至真要大论篇第七十四","description":"<p>188、风气大来。木之胜也。土湿受邪。脾病生焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202663,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '188、风气大来。木之胜也。土湿受邪。脾病生焉。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5dgxY3ZhOu1', 4, '{"title":"第20202664条・至真要大论篇第七十四","description":"<p>189、所谓感邪而生病也。乘年之虚。则邪甚也。失时之和。亦邪甚也。遇月之空。亦邪甚也。重感于邪。则病危矣。有胜之气。其必来复也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202664,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '189、所谓感邪而生病也。乘年之虚。则邪甚也。失时之和。亦邪甚也。遇月之空。亦邪甚也。重感于邪。则病危矣。有胜之气。其必来复也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7KEBHBEgdBE', 4, '{"title":"第20202665条・至真要大论篇第七十四","description":"<p>190、帝曰：其脉至何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202665,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '190、帝曰：其脉至何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JzWFdzwZJg3', 4, '{"title":"第20202666条・至真要大论篇第七十四","description":"<p>191、岐伯曰：厥阴之至其脉弦。少阴之至其脉钩。太阴之至其脉沉。少阳之至大而浮。阳明之至短而涩。太阳之至大而长。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202666,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '191、岐伯曰：厥阴之至其脉弦。少阴之至其脉钩。太阴之至其脉沉。少阳之至大而浮。阳明之至短而涩。太阳之至大而长。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KKfmDTlYTyA', 4, '{"title":"第20202667条・至真要大论篇第七十四","description":"<p>192、至而和则平。至而甚则病。至而反者病。至而不至者病。未至而至者病。阴阳易者危。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202667,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '192、至而和则平。至而甚则病。至而反者病。至而不至者病。未至而至者病。阴阳易者危。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Xf0F5gmEmj', 4, '{"title":"第20202668条・至真要大论篇第七十四","description":"<p>193、帝曰：六气标本。所从不同奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202668,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '193、帝曰：六气标本。所从不同奈何？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d37PLw8uiiX', 4, '{"title":"第20202669条・至真要大论篇第七十四","description":"<p>194、岐伯曰：气有从本者。有从标本者。有不从标本者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202669,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '194、岐伯曰：气有从本者。有从标本者。有不从标本者也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NMN1Y89cbV4', 4, '{"title":"第20202670条・至真要大论篇第七十四","description":"<p>195、帝曰：愿卒闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202670,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '195、帝曰：愿卒闻之。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a3D2nY7HU6e', 4, '{"title":"第20202671条・至真要大论篇第七十四","description":"<p>196、岐伯曰：少阳太阴从本。少阴太阳从本从标。阳明厥阴。不从标本从乎中也。故从本者化生于本。从标本者有标本之化。从中者以中气为化也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202671,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '196、岐伯曰：少阳太阴从本。少阴太阳从本从标。阳明厥阴。不从标本从乎中也。故从本者化生于本。从标本者有标本之化。从中者以中气为化也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rUhef144T48', 4, '{"title":"第20202672条・至真要大论篇第七十四","description":"<p>197、帝曰：脉从 而病反者。其诊何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202672,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '197、帝曰：脉从 而病反者。其诊何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
