INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2oChA9sNlJk', 4, '{"title":"第20202674条・至真要大论篇第七十四","description":"<p>199、帝曰：诸阴之反。其脉何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202674,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '199、帝曰：诸阴之反。其脉何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pjsToFU3r3m', 4, '{"title":"第20202675条・至真要大论篇第七十四","description":"<p>200、岐伯曰：脉至而从。按之鼓甚而盛也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202675,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '200、岐伯曰：脉至而从。按之鼓甚而盛也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('miYs5h1raRa', 4, '{"title":"第20202676条・至真要大论篇第七十四","description":"<p>201、是故百病之起。有生于本者。有生于标者。有生于中气者。有取本而得者。有取标而得者。有取中气而得者。有取标本而得者。有逆取而得者。有从取而得者。逆。正顺也。若顺。逆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202676,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '201、是故百病之起。有生于本者。有生于标者。有生于中气者。有取本而得者。有取标而得者。有取中气而得者。有取标本而得者。有逆取而得者。有从取而得者。逆。正顺也。若顺。逆也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wgEChjr3UX7', 4, '{"title":"第20202677条・至真要大论篇第七十四","description":"<p>202、故曰：知标与本。用之不殆。明知逆顺。正行无问。此之谓也。不知是者。不足以言诊。足以乱经。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202677,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '202、故曰：知标与本。用之不殆。明知逆顺。正行无问。此之谓也。不知是者。不足以言诊。足以乱经。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KIfAOso4U1b', 4, '{"title":"第20202678条・至真要大论篇第七十四","description":"<p>203、故《大要》曰：粗工嘻嘻。以为可知。言热未已。寒病复始。同气异形。迷诊乱经。此之谓也。夫标本之道。要而博。小而大。可以言一而知百病之害。言标与本。易而勿损。察本与标。气可令调。明知胜复。为万民式。天之道毕矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202678,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '203、故《大要》曰：粗工嘻嘻。以为可知。言热未已。寒病复始。同气异形。迷诊乱经。此之谓也。夫标本之道。要而博。小而大。可以言一而知百病之害。言标与本。易而勿损。察本与标。气可令调。明知胜复。为万民式。天之道毕矣。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ue5XPD4KocH', 4, '{"title":"第20202679条・至真要大论篇第七十四","description":"<p>204、帝曰：胜复之变。早晏何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202679,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '204、帝曰：胜复之变。早晏何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z5aCM157moB', 4, '{"title":"第20202680条・至真要大论篇第七十四","description":"<p>205、岐伯曰：夫所胜者。胜至已病。病已愠愠。而复已萌也。夫所复者。胜尽而起。得位而甚。胜有微甚。复有少多。胜和而和。胜虚而虚。天之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202680,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '205、岐伯曰：夫所胜者。胜至已病。病已愠愠。而复已萌也。夫所复者。胜尽而起。得位而甚。胜有微甚。复有少多。胜和而和。胜虚而虚。天之常也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y4gKWOyHcgH', 4, '{"title":"第20202681条・至真要大论篇第七十四","description":"<p>206、帝曰：胜复之作。动不当位。或后时而至。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202681,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '206、帝曰：胜复之作。动不当位。或后时而至。其故何也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wCEQVbbpZ2W', 4, '{"title":"第20202682条・至真要大论篇第七十四","description":"<p>207、岐伯曰： 夫气之生。与其化衰盛异也。寒暑温凉盛衰之用。其在四维。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202682,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '207、岐伯曰： 夫气之生。与其化衰盛异也。寒暑温凉盛衰之用。其在四维。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
