INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZJo1liwjZ02', 4, '{"title":"第20202696条・至真要大论篇第七十四","description":"<p>221、帝曰：夫子言春秋气始于前。冬夏气始于后。余已知之矣。然六气往复。主岁不常也。其补泻奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202696,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '221、帝曰：夫子言春秋气始于前。冬夏气始于后。余已知之矣。然六气往复。主岁不常也。其补泻奈何？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jr9gpRaEPGq', 4, '{"title":"第20202697条・至真要大论篇第七十四","description":"<p>222、岐伯曰：上下所主。随其攸利。正其味。则其要也。左右同法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202697,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '222、岐伯曰：上下所主。随其攸利。正其味。则其要也。左右同法。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y1FPHtjGlpr', 4, '{"title":"第20202698条・至真要大论篇第七十四","description":"<p>223、大要曰：少阳之主。先甘后咸。阳明之主。先辛后酸。太阳之主。先咸后苦。厥阴之主。先酸后辛。少阴之主。先甘后咸。太阴之主。先苦后甘。佐以所利。资以所生。是谓得气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202698,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '223、大要曰：少阳之主。先甘后咸。阳明之主。先辛后酸。太阳之主。先咸后苦。厥阴之主。先酸后辛。少阴之主。先甘后咸。太阴之主。先苦后甘。佐以所利。资以所生。是谓得气。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MgNrn0iWwKv', 4, '{"title":"第20202699条・至真要大论篇第七十四","description":"<p>224、帝曰：善。夫百病之生也。皆生于风寒暑湿燥火。以之化之变也。经言盛者泻之。虚者补之。余锡以方士。而方士用之尚未能十全。余欲令要道必行。桴鼓相应。犹拔刺雪污。工巧神圣。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202699,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '224、帝曰：善。夫百病之生也。皆生于风寒暑湿燥火。以之化之变也。经言盛者泻之。虚者补之。余锡以方士。而方士用之尚未能十全。余欲令要道必行。桴鼓相应。犹拔刺雪污。工巧神圣。可得闻乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ifJIKqTZ2R2', 4, '{"title":"第20202700条・至真要大论篇第七十四","description":"<p>225、岐伯曰：审察病机，无失气宜，此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202700,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '225、岐伯曰：审察病机，无失气宜，此之谓也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
