INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oiY9thK0bUv', 4, '{"title":"第20202731条・至真要大论篇第七十四","description":"<p>256、寒者热之。热者寒之。微者逆之。甚者从之。坚者削之。客者除之。劳者温之。结者散之。留者攻之。燥者濡之。急者缓之。散者收之。损者温之。逸者行之。惊者平之。上之下之。摩之浴之。薄之劫之。开之发之。适事为故。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202731,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '256、寒者热之。热者寒之。微者逆之。甚者从之。坚者削之。客者除之。劳者温之。结者散之。留者攻之。燥者濡之。急者缓之。散者收之。损者温之。逸者行之。惊者平之。上之下之。摩之浴之。薄之劫之。开之发之。适事为故。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
