INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UIrZeZYjFO5', 4, '{"title":"第20202733条・至真要大论篇第七十四","description":"<p>258、岐伯曰：逆者正治。从者反治。从少从多。观其事也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202733,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '258、岐伯曰：逆者正治。从者反治。从少从多。观其事也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wh2HzOTyAoZ', 4, '{"title":"第20202734条・至真要大论篇第七十四","description":"<p>259、帝曰：反治何谓？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202734,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '259、帝曰：反治何谓？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cZkGNtXBQce', 4, '{"title":"第20202735条・至真要大论篇第七十四","description":"<p>260、岐伯 曰：热因寒用。寒因热用。塞因塞用。通因通用。必伏其所主。而先其所因。其始则同。其终则异。可使破积。可使溃坚。可使气和。可使必已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202735,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '260、岐伯 曰：热因寒用。寒因热用。塞因塞用。通因通用。必伏其所主。而先其所因。其始则同。其终则异。可使破积。可使溃坚。可使气和。可使必已。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c3xkfBXojh8', 4, '{"title":"第20202736条・至真要大论篇第七十四","description":"<p>261、帝曰：善。气调而得者何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202736,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '261、帝曰：善。气调而得者何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fD84QbKvZyE', 4, '{"title":"第20202737条・至真要大论篇第七十四","description":"<p>262、岐伯曰：逆之从之。逆而从之。从而逆之。疏气令调。则其道也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202737,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '262、岐伯曰：逆之从之。逆而从之。从而逆之。疏气令调。则其道也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4e9PS3MqZ9N', 4, '{"title":"第20202738条・至真要大论篇第七十四","description":"<p>263、帝曰：善。病之中外何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202738,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '263、帝曰：善。病之中外何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KR1IakDHQhm', 4, '{"title":"第20202739条・至真要大论篇第七十四","description":"<p>264、岐伯曰：从内之外者。调其内。从外之内者。治其外。从内之外而盛于外者。先调其内而后治其外。从外之内而盛于内者。先治其外而后调其内。中外不相及。则治主病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202739,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '264、岐伯曰：从内之外者。调其内。从外之内者。治其外。从内之外而盛于外者。先调其内而后治其外。从外之内而盛于内者。先治其外而后调其内。中外不相及。则治主病。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5CwfPMXh6lk', 4, '{"title":"第20202740条・至真要大论篇第七十四","description":"<p>265、帝曰：善。火热复。恶寒发热。有如疟状。或一日发。或间数日发。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202740,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '265、帝曰：善。火热复。恶寒发热。有如疟状。或一日发。或间数日发。其故何也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AtYdcDhWSD0', 4, '{"title":"第20202741条・至真要大论篇第七十四","description":"<p>266、岐伯曰：胜复之气。会遇之时。有多少也。阴气多而阳气少。则其发日远。阳气多而阴气少。则其发日近。此胜复相薄。盛衰之节。 疟亦同法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202741,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '266、岐伯曰：胜复之气。会遇之时。有多少也。阴气多而阳气少。则其发日远。阳气多而阴气少。则其发日近。此胜复相薄。盛衰之节。 疟亦同法。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KLz5i8YiWYA', 4, '{"title":"第20202742条・至真要大论篇第七十四","description":"<p>267、帝曰：论言治寒以热。治热以寒。而方士不能废绳墨而更其道也。有病热者寒之而热。有病寒者热之而寒。二者皆在。新病复起。奈何治？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202742,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '267、帝曰：论言治寒以热。治热以寒。而方士不能废绳墨而更其道也。有病热者寒之而热。有病寒者热之而寒。二者皆在。新病复起。奈何治？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iHhWOHNd7Qi', 4, '{"title":"第20202743条・至真要大论篇第七十四","description":"<p>268、岐伯曰：诸寒之而热者取之阴。热之而寒者取之阳。所谓求其属也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202743,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '268、岐伯曰：诸寒之而热者取之阴。热之而寒者取之阳。所谓求其属也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3h4eRwgtf3p', 4, '{"title":"第20202744条・至真要大论篇第七十四","description":"<p>269、帝曰：善。服寒而反热。服热而反寒。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202744,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '269、帝曰：善。服寒而反热。服热而反寒。其故何也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v1L7BNLzjxW', 4, '{"title":"第20202745条・至真要大论篇第七十四","description":"<p>270、岐伯曰：治其王气。是以反也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202745,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '270、岐伯曰：治其王气。是以反也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
