INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3EG4FpCfmua', 4, '{"title":"第20202747条・至真要大论篇第七十四","description":"<p>272、岐伯曰：悉乎哉问也！不治五味属也。夫五味入胃。各归所喜。故酸先入肝。苦先入心。甘先入脾。辛先入肺。咸先入肾。久而增气。物化之常也。气增而久。夭之由也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202747,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '272、岐伯曰：悉乎哉问也！不治五味属也。夫五味入胃。各归所喜。故酸先入肝。苦先入心。甘先入脾。辛先入肺。咸先入肾。久而增气。物化之常也。气增而久。夭之由也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
