INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lib9KudiPtW', 4, '{"title":"第20202753条・至真要大论篇第七十四","description":"<p>278、岐伯曰：调气之方。必别阴阳。定其中外。各守其乡。内者内治。外者外治。微者调之。其次平之。盛者夺之。汗之下之。寒热温凉。衰之以属。随其攸利。谨道如法。万举万全。气血正平。长有天命。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202753,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '278、岐伯曰：调气之方。必别阴阳。定其中外。各守其乡。内者内治。外者外治。微者调之。其次平之。盛者夺之。汗之下之。寒热温凉。衰之以属。随其攸利。谨道如法。万举万全。气血正平。长有天命。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('khehnYLVfmd', 4, '{"title":"第20202754条・至真要大论篇第七十四","description":"<p>279、帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202754,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '279、帝曰：善。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ds7Hmad0QlC', 4, '{"title":"第20202755条・著至教论篇第七十五","description":"<p>1、黄帝坐明堂。召雷公而问之曰：子知医之道乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202755,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、黄帝坐明堂。召雷公而问之曰：子知医之道乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hd8ax5CZyGY', 4, '{"title":"第20202756条・著至教论篇第七十五","description":"<p>2、雷公对曰：诵而未能解。解而未能别。别而未能明。明而未能彰。足以治群僚。不足治侯王。愿得受树天之度。四时阴阳合之。别星辰与日月光。以彰经术。后世益明。上通神农。着至教疑于二皇。    帝曰：善。无失之。此皆阴阳表里上下雌雄相输应也。而道上知天文。下知地理。中知人事。可以长久。以教众庶。亦不疑殆。医道论篇。可传后世。可以为宝。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202756,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2、雷公对曰：诵而未能解。解而未能别。别而未能明。明而未能彰。足以治群僚。不足治侯王。愿得受树天之度。四时阴阳合之。别星辰与日月光。以彰经术。后世益明。上通神农。着至教疑于二皇。 帝曰：善。无失之。此皆阴阳表里上下雌雄相输应也。而道上知天文。下知地理。中知人事。可以长久。以教众庶。亦不疑殆。医道论篇。可传后世。可以为宝。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KbjH80oxi19', 4, '{"title":"第20202757条・著至教论篇第七十五","description":"<p>3、雷公曰：请受道。讽诵用解。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202757,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '3、雷公曰：请受道。讽诵用解。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
