INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wCxhSnUbgmA', 4, '{"title":"第20202760条・著至教论篇第七十五","description":"<p>6、曰：夫三阳天为业。上下无常。合而病至。偏害阴阳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202760,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '6、曰：夫三阳天为业。上下无常。合而病至。偏害阴阳。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZF8w879Hv79', 4, '{"title":"第20202761条・著至教论篇第七十五","description":"<p>7、雷公曰：三阳莫当。请闻其解。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202761,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '7、雷公曰：三阳莫当。请闻其解。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iGW22Sv7WoH', 4, '{"title":"第20202762条・著至教论篇第七十五","description":"<p>8、帝曰：三阳独至者。是三阳并至。并至如风雨。上为巅疾。下为漏病。外无期。内无正。不中经纪。诊无上下。以书别。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202762,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '8、帝曰：三阳独至者。是三阳并至。并至如风雨。上为巅疾。下为漏病。外无期。内无正。不中经纪。诊无上下。以书别。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EJT25khMvra', 4, '{"title":"第20202763条・著至教论篇第七十五","description":"<p>9、雷公曰：臣治疏愈。说意而已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202763,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '9、雷公曰：臣治疏愈。说意而已。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iyeFQq29jLn', 4, '{"title":"第20202764条・著至教论篇第七十五","description":"<p>10、帝曰：三阳者。至阳也。积并则为惊。病起疾风。至如礔砺。九窍皆塞。阳气滂溢。干嗌喉塞。并于阴。则上下无常。薄为肠澼。此谓三阳直心，坐不 得起，卧者便身全，三阳之病。且以知天下。何以别阴阳。应四时。合之五行。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202764,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '10、帝曰：三阳者。至阳也。积并则为惊。病起疾风。至如礔砺。九窍皆塞。阳气滂溢。干嗌喉塞。并于阴。则上下无常。薄为肠澼。此谓三阳直心，坐不 得起，卧者便身全，三阳之病。且以知天下。何以别阴阳。应四时。合之五行。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('niZMgt678Bb', 4, '{"title":"第20202765条・著至教论篇第七十五","description":"<p>11、雷公曰：阳言不别。阴言不理。请起受解。以为至道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202765,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '11、雷公曰：阳言不别。阴言不理。请起受解。以为至道。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('klCEZRMK68M', 4, '{"title":"第20202766条・著至教论篇第七十五","description":"<p>12、帝曰：子若受传。不知合至道以惑师教。语子至道之要。病伤五脏。筋骨以消。子言不明不别。是世主学尽矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202766,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '12、帝曰：子若受传。不知合至道以惑师教。语子至道之要。病伤五脏。筋骨以消。子言不明不别。是世主学尽矣。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RSE1oEr0KFM', 4, '{"title":"第20202767条・著至教论篇第七十五","description":"<p>13、肾且绝。惋惋日暮。从容不出。人事不殷。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202767,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '13、肾且绝。惋惋日暮。从容不出。人事不殷。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'BIiSSRgPRkn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rO3aHLFr2z4', 4, '{"title":"第20202768条・示从容论篇第七十六","description":"<p>1、黄帝燕坐。召雷公而问之曰：汝受术诵书者。若能览观杂学。及于比类。通合道理。为余言子所长。五藏六腑。胆胃大小肠脾胞膀胱。脑髓涕唾。哭泣悲哀。。水所从行。此皆人之所生。治之过失，子务明之。可以十全。即不能知。为世所怨。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202768,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、黄帝燕坐。召雷公而问之曰：汝受术诵书者。若能览观杂学。及于比类。通合道理。为余言子所长。五藏六腑。胆胃大小肠脾胞膀胱。脑髓涕唾。哭泣悲哀。。水所从行。此皆人之所生。治之过失，子务明之。可以十全。即不能知。为世所怨。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JGuQXpk7ozk', 4, '{"title":"第20202769条・示从容论篇第七十六","description":"<p>2、雷公曰：臣请诵《脉经·上下编》甚众多矣。别异比类。犹未能以十全。又安足以明之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202769,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2、雷公曰：臣请诵《脉经·上下编》甚众多矣。别异比类。犹未能以十全。又安足以明之。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TdaZvaNzrn6', 4, '{"title":"第20202770条・示从容论篇第七十六","description":"<p>3、帝曰：子别试通五脏之过。六腑之所不和。针石之败。毒药所宜。汤液滋味。具言其状。悉言以对。请问不知。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202770,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '3、帝曰：子别试通五脏之过。六腑之所不和。针石之败。毒药所宜。汤液滋味。具言其状。悉言以对。请问不知。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oxw3MR82j7g', 4, '{"title":"第20202771条・示从容论篇第七十六","description":"<p>4、雷公曰：肝虚肾虚脾虚。皆令人体重烦冤。当投毒药刺灸砭石汤液。或已或不已。愿闻其解。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202771,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '4、雷公曰：肝虚肾虚脾虚。皆令人体重烦冤。当投毒药刺灸砭石汤液。或已或不已。愿闻其解。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yixt44bFkjO', 4, '{"title":"第20202772条・示从容论篇第七十六","description":"<p>5、帝曰：公何年之长而问之少。余真问以自谬也。吾问子窈冥。子言上下编以对。何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202772,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '5、帝曰：公何年之长而问之少。余真问以自谬也。吾问子窈冥。子言上下编以对。何也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w5KjOzLNWfj', 4, '{"title":"第20202773条・示从容论篇第七十六","description":"<p>6、夫脾虚浮似肺。肾小浮似脾。肝急沉散似肾。此皆工之所时乱也。然从容得之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202773,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '6、夫脾虚浮似肺。肾小浮似脾。肝急沉散似肾。此皆工之所时乱也。然从容得之。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IN9GfJf6Juj', 4, '{"title":"第20202774条・示从容论篇第七十六","description":"<p>7、若夫三藏土木水参居。此童子之所知。问之何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202774,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '7、若夫三藏土木水参居。此童子之所知。问之何也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ke2Ee8YRmv1', 4, '{"title":"第20202775条・示从容论篇第七十六","description":"<p>8、雷公曰：于此有人。头痛筋挛骨重。怯然少气。哕噫腹满。时惊不嗜卧。此何藏之发也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202775,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '8、雷公曰：于此有人。头痛筋挛骨重。怯然少气。哕噫腹满。时惊不嗜卧。此何藏之发也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MaskLNiQGED', 4, '{"title":"第20202776条・示从容论篇第七十六","description":"<p>9、脉浮而弦。切之石坚。不知其解。复问所以三脏者。以知其比类也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202776,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '9、脉浮而弦。切之石坚。不知其解。复问所以三脏者。以知其比类也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vMKG23OmQlg', 4, '{"title":"第20202777条・示从容论篇第七十六","description":"<p>10、帝曰：夫从容之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202777,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '10、帝曰：夫从容之谓也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q7BXOIA5NMg', 4, '{"title":"第20202778条・示从容论篇第七十六","description":"<p>11、夫年长则求之于腑。年少则求之于经。年壮则求之于藏。今子所言皆失。八风菀熟。五藏消烁。传邪相受。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202778,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '11、夫年长则求之于腑。年少则求之于经。年壮则求之于藏。今子所言皆失。八风菀熟。五藏消烁。传邪相受。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EotsuaPD5Xx', 4, '{"title":"第20202779条・示从容论篇第七十六","description":"<p>12、夫浮而弦者。是肾不足也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202779,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '12、夫浮而弦者。是肾不足也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9HPVnxE1CwE', 4, '{"title":"第20202780条・示从容论篇第七十六","description":"<p>13、沉而石者。是肾气内着也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202780,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '13、沉而石者。是肾气内着也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XriIojL7jvC', 4, '{"title":"第20202781条・示从容论篇第七十六","description":"<p>14、怯然少气者。是水道不行。形气消索也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202781,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '14、怯然少气者。是水道不行。形气消索也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YNZc8xwMSjS', 4, '{"title":"第20202782条・示从容论篇第七十六","description":"<p>15、咳嗽烦冤者。是肾气之逆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202782,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '15、咳嗽烦冤者。是肾气之逆也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vw1mW4Yhl7L', 4, '{"title":"第20202783条・示从容论篇第七十六","description":"<p>16、一人之气。病在一藏也。若言三藏俱行。不在法也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202783,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '16、一人之气。病在一藏也。若言三藏俱行。不在法也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WaFUvVw4iA3', 4, '{"title":"第20202784条・示从容论篇第七十六","description":"<p>17、雷公曰：于此有人。四肢解惰。喘咳血泄。而愚诊之。以为伤肺。切脉浮大而紧。愚不敢治。粗工下砭石。病愈多出血。血止身轻。此何物也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202784,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '17、雷公曰：于此有人。四肢解惰。喘咳血泄。而愚诊之。以为伤肺。切脉浮大而紧。愚不敢治。粗工下砭石。病愈多出血。血止身轻。此何物也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dsUbkzYB0yZ', 4, '{"title":"第20202785条・示从容论篇第七十六","description":"<p>18、帝曰：子所能治。知亦众多。与此病失矣。譬以鸿飞。亦冲于天。夫圣人之治病。循法守度。援物比类。化之冥冥。循上及下。何必守经。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202785,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '18、帝曰：子所能治。知亦众多。与此病失矣。譬以鸿飞。亦冲于天。夫圣人之治病。循法守度。援物比类。化之冥冥。循上及下。何必守经。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hvwtw55abtN', 4, '{"title":"第20202786条・示从容论篇第七十六","description":"<p>19、今夫脉浮大虚者。是脾气之外绝。去胃外归阳明也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202786,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '19、今夫脉浮大虚者。是脾气之外绝。去胃外归阳明也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mBRTJLoW1Mc', 4, '{"title":"第20202787条・示从容论篇第七十六","description":"<p>20、夫二火不胜三水。是以脉乱而无常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202787,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '20、夫二火不胜三水。是以脉乱而无常也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UnCTInSvLKD', 4, '{"title":"第20202788条・示从容论篇第七十六","description":"<p>21、四肢解惰。此脾精之不行也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202788,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '21、四肢解惰。此脾精之不行也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0BpKW3EziWN', 4, '{"title":"第20202789条・示从容论篇第七十六","description":"<p>22、喘咳者。是水气并阳明也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202789,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '22、喘咳者。是水气并阳明也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('04jC2PLn5zp', 4, '{"title":"第20202790条・示从容论篇第七十六","description":"<p>23、血泄者。脉急血无所行也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202790,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '23、血泄者。脉急血无所行也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JoR27HLQ6Ae', 4, '{"title":"第20202791条・示从容论篇第七十六","description":"<p>24、若夫以为伤肺者。由失以狂也。不引比类。是知不明也。夫伤肺者。脾气不守。胃气不清。经气不为使。真藏坏决。经脉旁绝。五藏漏泄。不衄则呕。此二者不相类也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202791,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '24、若夫以为伤肺者。由失以狂也。不引比类。是知不明也。夫伤肺者。脾气不守。胃气不清。经气不为使。真藏坏决。经脉旁绝。五藏漏泄。不衄则呕。此二者不相类也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cL9l6cSwSJc', 4, '{"title":"第20202792条・示从容论篇第七十六","description":"<p>25、譬如天之无形。地之无理。白与黑相去远矣。是失吾过矣。以子知之。故不告子。明引比类《从容》。是以名曰诊轻。是谓至道也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202792,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '25、譬如天之无形。地之无理。白与黑相去远矣。是失吾过矣。以子知之。故不告子。明引比类《从容》。是以名曰诊轻。是谓至道也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'K7svZUe3oCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DTlfRLVX8Xt', 4, '{"title":"第20202793条・五过论篇第七十七","description":"<p>1、黄帝曰：呜呼远哉！闵闵乎若视深渊。若迎浮云。视深渊尚可测。迎浮云莫知其际。圣人之术。为万民式。论裁志意。必有法则。循经守数。按循医事。为万民副。故事有五过四德。汝知之乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202793,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、黄帝曰：呜呼远哉！闵闵乎若视深渊。若迎浮云。视深渊尚可测。迎浮云莫知其际。圣人之术。为万民式。论裁志意。必有法则。循经守数。按循医事。为万民副。故事有五过四德。汝知之乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G6tH8i9YNqq', 4, '{"title":"第20202794条・五过论篇第七十七","description":"<p>2、雷公避席再拜曰：臣年幼小。蒙愚以惑。不闻五过与四德。比类形名。虚引其经。心无所对。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202794,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2、雷公避席再拜曰：臣年幼小。蒙愚以惑。不闻五过与四德。比类形名。虚引其经。心无所对。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8KRuHjX6YPU', 4, '{"title":"第20202795条・五过论篇第七十七","description":"<p>3、帝曰：凡未诊病者。必问尝贵后贱。虽不中邪。病从内生。名曰脱营。尝富后贫。名曰失精。五气留连。病有所并。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202795,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '3、帝曰：凡未诊病者。必问尝贵后贱。虽不中邪。病从内生。名曰脱营。尝富后贫。名曰失精。五气留连。病有所并。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('anU46AT47pV', 4, '{"title":"第20202796条・五过论篇第七十七","description":"<p>4、医工诊之。不在脏腑。不变躯形。诊之而疑。不知病名。身体日减。气虚无精。病深无气。洒洒然时惊。病深者。以其外耗于卫。内夺于荣。良工所失。不知病情。此亦治之一过也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202796,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '4、医工诊之。不在脏腑。不变躯形。诊之而疑。不知病名。身体日减。气虚无精。病深无气。洒洒然时惊。病深者。以其外耗于卫。内夺于荣。良工所失。不知病情。此亦治之一过也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gYKZ2xWWhSO', 4, '{"title":"第20202797条・五过论篇第七十七","description":"<p>5、凡欲诊病者。必问饮食居处。暴乐暴苦。始乐后苦。皆伤精气。精气竭绝。形体毁沮。暴怒伤阴。暴喜伤阳。厥气上行。满脉去形。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202797,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '5、凡欲诊病者。必问饮食居处。暴乐暴苦。始乐后苦。皆伤精气。精气竭绝。形体毁沮。暴怒伤阴。暴喜伤阳。厥气上行。满脉去形。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ltYHb7m3B3y', 4, '{"title":"第20202798条・五过论篇第七十七","description":"<p>6、愚医治之。不知补泻。不知病情。精华日脱。邪气乃并。此治之二过也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202798,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '6、愚医治之。不知补泻。不知病情。精华日脱。邪气乃并。此治之二过也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SznNRaXMsCz', 4, '{"title":"第20202799条・五过论篇第七十七","description":"<p>7、善为脉者。必以比类奇恒从容知之。为工而不知道。此诊之不足贵。此治之三过也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202799,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '7、善为脉者。必以比类奇恒从容知之。为工而不知道。此诊之不足贵。此治之三过也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ij62hrDolCW', 4, '{"title":"第20202800条・五过论篇第七十七","description":"<p>8、诊有三常。必问贵贱。封君败伤。及欲侯王。故贵脱势。虽不中邪。精神内伤。身必败亡。始富后贫。虽不伤邪。皮焦筋屈。痿躄为挛。医不能严。不能动神。外为柔弱。乱至失常。病不能移。则医事不行。此治之四过也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202800,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '8、诊有三常。必问贵贱。封君败伤。及欲侯王。故贵脱势。虽不中邪。精神内伤。身必败亡。始富后贫。虽不伤邪。皮焦筋屈。痿躄为挛。医不能严。不能动神。外为柔弱。乱至失常。病不能移。则医事不行。此治之四过也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('52nrTAxgwTU', 4, '{"title":"第20202801条・五过论篇第七十七","description":"<p>9、凡诊者。必知终始。有知余绪。切脉问名。当合男女。离绝菀结。忧恐喜怒。五脏空虚。血气离守。工不能知。何术之语。尝富大伤。斩筋绝脉。身体复行。令泽不息。故伤败结。留薄归阳。脓积寒炅。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '9、凡诊者。必知终始。有知余绪。切脉问名。当合男女。离绝菀结。忧恐喜怒。五脏空虚。血气离守。工不能知。何术之语。尝富大伤。斩筋绝脉。身体复行。令泽不息。故伤败结。留薄归阳。脓积寒炅。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w6pewebGa6k', 4, '{"title":"第20202802条・五过论篇第七十七","description":"<p>10、粗工治之。亟刺阴阳。身体解散。四肢转筋。死日有期。医不能明。不问所发。唯言死日。亦为粗工。此治之五过也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202802,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '10、粗工治之。亟刺阴阳。身体解散。四肢转筋。死日有期。医不能明。不问所发。唯言死日。亦为粗工。此治之五过也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wWmemsaJkAq', 4, '{"title":"第20202803条・五过论篇第七十七","description":"<p>11、凡此五者。皆受术不通。人事不明也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202803,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '11、凡此五者。皆受术不通。人事不明也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LSmpCRgk5ho', 4, '{"title":"第20202804条・五过论篇第七十七","description":"<p>12、故曰：圣人之治病也。必知天地阴阳。四时经纪。五脏六腑。雌雄表里。刺灸砭石。毒药所主。从容人事。以明经道。贵贱贫富。各异品理。问年少长。勇怯之理。审于分部。知病本始。八正九候。诊必副矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202804,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '12、故曰：圣人之治病也。必知天地阴阳。四时经纪。五脏六腑。雌雄表里。刺灸砭石。毒药所主。从容人事。以明经道。贵贱贫富。各异品理。问年少长。勇怯之理。审于分部。知病本始。八正九候。诊必副矣。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WOkow6o0GIN', 4, '{"title":"第20202805条・五过论篇第七十七","description":"<p>13、治病之道。气内为宝。循求其理。求之不得。过在表里。守数据治。无失俞理。能行此术。终身不殆。不知俞理。五藏菀熟。痈发六腑。诊病不审。是谓失常。谨守此治。与经相明。《上经》、《下经》。揆度阴阳。奇恒五中。决以明堂。审于终始。可以横行。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202805,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '13、治病之道。气内为宝。循求其理。求之不得。过在表里。守数据治。无失俞理。能行此术。终身不殆。不知俞理。五藏菀熟。痈发六腑。诊病不审。是谓失常。谨守此治。与经相明。《上经》、《下经》。揆度阴阳。奇恒五中。决以明堂。审于终始。可以横行。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'OmA7rGIg9YG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('33NO6sYebbs', 4, '{"title":"第20202806条・征四失论篇第七十八","description":"<p>1、黄帝在明堂。雷公侍坐。黄帝曰：夫子所通书受事众多矣。试言得失之意。所以得之。所以失之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202806,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、黄帝在明堂。雷公侍坐。黄帝曰：夫子所通书受事众多矣。试言得失之意。所以得之。所以失之。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AcmTEuaWdg7', 4, '{"title":"第20202807条・征四失论篇第七十八","description":"<p>2、雷公对曰：循经受业。皆言十全。其时有过失者。请闻其事解也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202807,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2、雷公对曰：循经受业。皆言十全。其时有过失者。请闻其事解也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yCxgoZxSluK', 4, '{"title":"第20202808条・征四失论篇第七十八","description":"<p>3、帝曰：子年少智未及邪？将言以杂合耶？夫经脉十二。络脉三百六十五。此皆人之所明知。工之所循用也。所以不十全者。精神不专。志意不理。外内相失。 故时疑殆。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202808,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '3、帝曰：子年少智未及邪？将言以杂合耶？夫经脉十二。络脉三百六十五。此皆人之所明知。工之所循用也。所以不十全者。精神不专。志意不理。外内相失。 故时疑殆。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OYfhUzdQQsa', 4, '{"title":"第20202809条・征四失论篇第七十八","description":"<p>4、诊不知阴阳逆从之理。此治之一失矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202809,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '4、诊不知阴阳逆从之理。此治之一失矣。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lRqHq6utj9W', 4, '{"title":"第20202810条・征四失论篇第七十八","description":"<p>5、受师不卒。妄作杂术。谬言为道。更名自功。妄用砭石。后遗身咎。此治之二失也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202810,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '5、受师不卒。妄作杂术。谬言为道。更名自功。妄用砭石。后遗身咎。此治之二失也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f5TuIidGr2R', 4, '{"title":"第20202811条・征四失论篇第七十八","description":"<p>6、不适贫富贵贱之居。坐之薄浓。形之寒温。不适饮食之宜。不别人之勇怯。不知比类。足以自乱。不足以自明。此治之三失也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202811,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '6、不适贫富贵贱之居。坐之薄浓。形之寒温。不适饮食之宜。不别人之勇怯。不知比类。足以自乱。不足以自明。此治之三失也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V5Dg4g307aZ', 4, '{"title":"第20202812条・征四失论篇第七十八","description":"<p>7、诊病不问其始。忧患饮食之失节。起居之过度。或伤于毒。不先言此。卒持寸口。何病能中。妄言作名。为粗所穷。此治之四失也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202812,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '7、诊病不问其始。忧患饮食之失节。起居之过度。或伤于毒。不先言此。卒持寸口。何病能中。妄言作名。为粗所穷。此治之四失也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9nF6i4uIaM9', 4, '{"title":"第20202813条・征四失论篇第七十八","description":"<p>8、是以世人之语者。驰千里之外。不明尺寸之论。诊无人事。治数之道。从容之葆。坐持寸口。诊不中五脉。百病所起。始以自怨。遗师其咎。是故治不能循理。弃术于市。妄治时愈。愚心自得。呜呼！窈窈冥冥。熟知其道？！道之大者。拟于天地。配于四海。汝不知道之谕。受以明为晦。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202813,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '8、是以世人之语者。驰千里之外。不明尺寸之论。诊无人事。治数之道。从容之葆。坐持寸口。诊不中五脉。百病所起。始以自怨。遗师其咎。是故治不能循理。弃术于市。妄治时愈。愚心自得。呜呼！窈窈冥冥。熟知其道？！道之大者。拟于天地。配于四海。汝不知道之谕。受以明为晦。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T4t1eFEnGvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yMUnZ0WMBhN', 4, '{"title":"第20202814条・阴阳类论篇第七十九","description":"<p>1、孟春始至。黄帝燕坐。临观八极。正八风之气。而问雷公曰：阴阳之类。经脉之道。五中所主。何藏最贵？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202814,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、孟春始至。黄帝燕坐。临观八极。正八风之气。而问雷公曰：阴阳之类。经脉之道。五中所主。何藏最贵？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kcUbfxw5iB2', 4, '{"title":"第20202815条・阴阳类论篇第七十九","description":"<p>2、雷公对曰：春甲乙青。中主肝。治七十二日。是脉之主时。臣以其藏最贵。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202815,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2、雷公对曰：春甲乙青。中主肝。治七十二日。是脉之主时。臣以其藏最贵。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lWMZIjpp7S3', 4, '{"title":"第20202816条・阴阳类论篇第七十九","description":"<p>3、帝曰：却念上下经阴阳从容。子所言贵。最其下也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202816,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '3、帝曰：却念上下经阴阳从容。子所言贵。最其下也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JEHsJP1hYM4', 4, '{"title":"第20202817条・阴阳类论篇第七十九","description":"<p>4、雷公致斋七日。旦复侍坐。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202817,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '4、雷公致斋七日。旦复侍坐。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hRuQcvtvAvU', 4, '{"title":"第20202818条・阴阳类论篇第七十九","description":"<p>5、帝曰：三阳为经。二阳为维。一阳为游部。此知五藏终始。三阴为表。二阴为里。一阴至绝作朔晦。却具合以正其理。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202818,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '5、帝曰：三阳为经。二阳为维。一阳为游部。此知五藏终始。三阴为表。二阴为里。一阴至绝作朔晦。却具合以正其理。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p5z7GxrOcJR', 4, '{"title":"第20202819条・阴阳类论篇第七十九","description":"<p>6、雷公曰：受业未能明。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202819,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '6、雷公曰：受业未能明。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Zjtroh2z7s0', 4, '{"title":"第20202820条・阴阳类论篇第七十九","description":"<p>7、帝曰：所谓三阳者。太阳为经。三阳脉至手太阴。弦浮而不沉。决以度。察以心。合之阴阳之论。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202820,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '7、帝曰：所谓三阳者。太阳为经。三阳脉至手太阴。弦浮而不沉。决以度。察以心。合之阴阳之论。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YXGNqRcesgb', 4, '{"title":"第20202821条・阴阳类论篇第七十九","description":"<p>8、所谓二阳者。阳明也。至手太阴。弦而沉急不鼓。炅至以病皆死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202821,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '8、所谓二阳者。阳明也。至手太阴。弦而沉急不鼓。炅至以病皆死。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jrjfqYE7F0Y', 4, '{"title":"第20202822条・阴阳类论篇第七十九","description":"<p>9、一阳者。少阳也。至手太阴。上连人迎。弦急悬不绝。此少阳之病也。专阴则死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202822,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '9、一阳者。少阳也。至手太阴。上连人迎。弦急悬不绝。此少阳之病也。专阴则死。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8LIcuLgDhhT', 4, '{"title":"第20202823条・阴阳类论篇第七十九","description":"<p>10、三阴者。六经之所主也。交于太阴。伏鼓不浮。上空志心。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202823,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '10、三阴者。六经之所主也。交于太阴。伏鼓不浮。上空志心。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xgRMcXs36dt', 4, '{"title":"第20202824条・阴阳类论篇第七十九","description":"<p>11、二阴至肺。其气归膀胱。外连脾胃。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202824,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '11、二阴至肺。其气归膀胱。外连脾胃。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
