INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bDkLn2NB7hJ', 4, '{"title":"第20202826条・阴阳类论篇第七十九","description":"<p>13、此六脉者。乍阴乍阳。交属相并。缪通五藏。合于阴阳。先至为主。后至为客。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202826,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '13、此六脉者。乍阴乍阳。交属相并。缪通五藏。合于阴阳。先至为主。后至为客。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2tZ8WZinBKB', 4, '{"title":"第20202827条・阴阳类论篇第七十九","description":"<p>14、雷公曰：臣悉尽意。 受传经脉。颂得从容之道。以合《从容》。不知阴阳。不知雌雄。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202827,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '14、雷公曰：臣悉尽意。 受传经脉。颂得从容之道。以合《从容》。不知阴阳。不知雌雄。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FH0zhAlLcju', 4, '{"title":"第20202828条・阴阳类论篇第七十九","description":"<p>15、帝曰：三阳为父。二阳为卫。一阳为纪。 三阴为母。二阴为雌。一阴为独使。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202828,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '15、帝曰：三阳为父。二阳为卫。一阳为纪。 三阴为母。二阴为雌。一阴为独使。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HgH0eLdy3je', 4, '{"title":"第20202829条・阴阳类论篇第七十九","description":"<p>16、二阳一阴。阳明主病。不胜一阴。脉緛而动。九窍皆沉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202829,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '16、二阳一阴。阳明主病。不胜一阴。脉緛而动。九窍皆沉。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
