INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FBe407QJ2An', 4, '{"title":"第20202833条・阴阳类论篇第七十九","description":"<p>20、二阴一阳。病出于肾。阴气客游于心。脘下空窍。堤闭塞不通。四肢别离。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202833,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '20、二阴一阳。病出于肾。阴气客游于心。脘下空窍。堤闭塞不通。四肢别离。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k4wftQMKJ04', 4, '{"title":"第20202834条・阴阳类论篇第七十九","description":"<p>21、一阴一阳代绝。此阴气至心。上下无常。出入不知。喉咽干燥。病在土脾。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202834,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '21、一阴一阳代绝。此阴气至心。上下无常。出入不知。喉咽干燥。病在土脾。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZikXwHOfuQM', 4, '{"title":"第20202835条・阴阳类论篇第七十九","description":"<p>22、二阳三阴。至阴皆在。阴不过阳。阳气不能止阴。阴阳并绝。浮为血瘕。沉为脓胕。阴阳皆壮。下至阴阳。上合昭昭。下合冥冥。诊决死生之期。遂合岁首。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202835,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '22、二阳三阴。至阴皆在。阴不过阳。阳气不能止阴。阴阳并绝。浮为血瘕。沉为脓胕。阴阳皆壮。下至阴阳。上合昭昭。下合冥冥。诊决死生之期。遂合岁首。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
