INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZVvHKxqwW1c', 4, '{"title":"第20202837条・阴阳类论篇第七十九","description":"<p>24、黄帝不应。雷公复问。黄帝曰。在经论中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202837,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '24、黄帝不应。雷公复问。黄帝曰。在经论中。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rTzotC58Int', 4, '{"title":"第20202838条・阴阳类论篇第七十九","description":"<p>25、雷公曰：请闻短期。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202838,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '25、雷公曰：请闻短期。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IF2sdVFDvGK', 4, '{"title":"第20202839条・阴阳类论篇第七十九","description":"<p>26、黄帝曰：冬三月之病。病合于阳者。至春正月脉有死征。皆归出春。冬三月之病。在理已尽。草与柳叶皆杀。春阴阳皆绝。期在孟春。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202839,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '26、黄帝曰：冬三月之病。病合于阳者。至春正月脉有死征。皆归出春。冬三月之病。在理已尽。草与柳叶皆杀。春阴阳皆绝。期在孟春。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q0IWIJGjIt3', 4, '{"title":"第20202840条・阴阳类论篇第七十九","description":"<p>27、春三月之病。曰阳杀。阴阳皆绝。期在草干。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202840,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '27、春三月之病。曰阳杀。阴阳皆绝。期在草干。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XmZjLvenU2a', 4, '{"title":"第20202841条・阴阳类论篇第七十九","description":"<p>28、夏三月之病。至阴不过十日。阴阳交。期在濂水。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202841,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '28、夏三月之病。至阴不过十日。阴阳交。期在濂水。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZnjYgmf5XLH', 4, '{"title":"第20202842条・阴阳类论篇第七十九","description":"<p>29、秋三月之病。三阳俱起。不治自已。阴阳交合者。 立不能坐。坐不能起。三阳独至。期在石水。二阴独至。期在盛水。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202842,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '29、秋三月之病。三阳俱起。不治自已。阴阳交合者。 立不能坐。坐不能起。三阳独至。期在石水。二阴独至。期在盛水。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'p4x3HeU2sgo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0XyMXIpmZlk', 4, '{"title":"第20202843条・方盛衰论篇第八十","description":"<p>1、雷公请问：气之多少。何者为逆？何者为从？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202843,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '1、雷公请问：气之多少。何者为逆？何者为从？', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HwxiBn2URMg', 4, '{"title":"第20202844条・方盛衰论篇第八十","description":"<p>2、黄帝答曰：阳从左。阴从右。老从上。少从下。是以春夏归阳为生。归秋冬为死。反之。则归秋冬为生。是以气之多少。逆皆为厥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202844,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2、黄帝答曰：阳从左。阴从右。老从上。少从下。是以春夏归阳为生。归秋冬为死。反之。则归秋冬为生。是以气之多少。逆皆为厥。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0cCe3OzLQx7', 4, '{"title":"第20202845条・方盛衰论篇第八十","description":"<p>3、问曰：有余者厥耶？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202845,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '3、问曰：有余者厥耶？', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('16xCHtpzV2o', 4, '{"title":"第20202846条・方盛衰论篇第八十","description":"<p>4、答曰： 一上不下。寒厥到膝。少者秋冬死。老者秋冬生。气上不下。头痛巅疾。求阳不得。求阴不审。五部隔无征。若居旷野。若伏空室。绵绵乎属不满日。是以少气之厥。令人妄梦。其极至迷。三阳绝，三阴微。是为少气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202846,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '4、答曰： 一上不下。寒厥到膝。少者秋冬死。老者秋冬生。气上不下。头痛巅疾。求阳不得。求阴不审。五部隔无征。若居旷野。若伏空室。绵绵乎属不满日。是以少气之厥。令人妄梦。其极至迷。三阳绝，三阴微。是为少气。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x4CG4Xnc77R', 4, '{"title":"第20202847条・方盛衰论篇第八十","description":"<p>5、是以肺气虚则使人梦见白物。见人斩血借借。得其时则梦见兵战。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202847,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '5、是以肺气虚则使人梦见白物。见人斩血借借。得其时则梦见兵战。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FowbEkuSYFh', 4, '{"title":"第20202848条・方盛衰论篇第八十","description":"<p>6、肾气虚则使人梦见舟船溺人。得其时则梦伏水中。若有畏恐。  肝气虚则梦见菌香生草。得其时则梦伏树下不敢起。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202848,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '6、肾气虚则使人梦见舟船溺人。得其时则梦伏水中。若有畏恐。 肝气虚则梦见菌香生草。得其时则梦伏树下不敢起。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JeyedrCC5xO', 4, '{"title":"第20202849条・方盛衰论篇第八十","description":"<p>7、心气虚则梦救火阳物。得其时则梦燔灼。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202849,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '7、心气虚则梦救火阳物。得其时则梦燔灼。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uLvRK5vS3Mm', 4, '{"title":"第20202850条・方盛衰论篇第八十","description":"<p>8、脾气虚则梦饮食不足。得其时则梦筑垣盖屋。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202850,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '8、脾气虚则梦饮食不足。得其时则梦筑垣盖屋。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QkFhvMUOjCo', 4, '{"title":"第20202851条・方盛衰论篇第八十","description":"<p>9、此皆五藏气虚。阳气有余。阴气不足。合之五诊。调之阴阳。以在《经脉》。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202851,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '9、此皆五藏气虚。阳气有余。阴气不足。合之五诊。调之阴阳。以在《经脉》。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4E24H4LkIZW', 4, '{"title":"第20202852条・方盛衰论篇第八十","description":"<p>10、诊有十度。度人脉度。藏度。肉度。筋度。俞度。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202852,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '10、诊有十度。度人脉度。藏度。肉度。筋度。俞度。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pxoI8iDYHCN', 4, '{"title":"第20202853条・方盛衰论篇第八十","description":"<p>11、阴阳气尽。人病自具。 脉动无常。散阴颇阳。 脉脱不具。诊无常行。诊必上下。度民君卿。受师不卒。使术不明。不察逆从。是为妄行。持雌失雄。弃阴附阳。不知并合。诊故不明。传之后世。反论自章。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202853,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '11、阴阳气尽。人病自具。 脉动无常。散阴颇阳。 脉脱不具。诊无常行。诊必上下。度民君卿。受师不卒。使术不明。不察逆从。是为妄行。持雌失雄。弃阴附阳。不知并合。诊故不明。传之后世。反论自章。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T6qdW3hr983', 4, '{"title":"第20202854条・方盛衰论篇第八十","description":"<p>12、至阴虚。天气绝。至阳盛。地气不足。阴阳并交。至人之所行。阴阳并交者。阳气先至。阴气后至。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202854,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '12、至阴虚。天气绝。至阳盛。地气不足。阴阳并交。至人之所行。阴阳并交者。阳气先至。阴气后至。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6xh26MXRKrb', 4, '{"title":"第20202855条・方盛衰论篇第八十","description":"<p>13、是以圣人持诊之道。先后阴阳而持之。奇恒之势乃六十首。诊合微之事。追阴阳之变。章五中之情。其中之论。取虚实之要。定五度之事。知此乃足以诊。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202855,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '13、是以圣人持诊之道。先后阴阳而持之。奇恒之势乃六十首。诊合微之事。追阴阳之变。章五中之情。其中之论。取虚实之要。定五度之事。知此乃足以诊。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wtslq6D6RYe', 4, '{"title":"第20202856条・方盛衰论篇第八十","description":"<p>14、是以切阴不得阳。诊消亡。得阳不得阴。守学不湛。知左不知右。知右不知左。知上不知下。知先不知后。故治不久。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202856,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '14、是以切阴不得阳。诊消亡。得阳不得阴。守学不湛。知左不知右。知右不知左。知上不知下。知先不知后。故治不久。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bXAWO5Uwkeb', 4, '{"title":"第20202857条・方盛衰论篇第八十","description":"<p>15、知丑知善。知病知不病。知高知下。知坐知起。知行知止。用之有纪。诊道乃具。万世不殆。起所有余。知所不足。度事上下。脉事因格。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202857,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '15、知丑知善。知病知不病。知高知下。知坐知起。知行知止。用之有纪。诊道乃具。万世不殆。起所有余。知所不足。度事上下。脉事因格。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C8WjJio7Q5d', 4, '{"title":"第20202858条・方盛衰论篇第八十","description":"<p>16、是以形弱气虚死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202858,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '16、是以形弱气虚死。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('48hwB3BY6C0', 4, '{"title":"第20202859条・方盛衰论篇第八十","description":"<p>17、形气有余。脉气不足死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202859,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '17、形气有余。脉气不足死。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mg8KWQ2Bix9', 4, '{"title":"第20202860条・方盛衰论篇第八十","description":"<p>18、脉气有余，形气不足生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202860,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '18、脉气有余，形气不足生。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vq90taVcGwE', 4, '{"title":"第20202861条・方盛衰论篇第八十","description":"<p>19、是以诊有大方。坐起有常。出入有行。以转神明。必清必净。上观下观。司八正邪。别五中部。按脉动静。循尺滑涩。寒温之意。视其大小。合之病能。逆从以得。复知病名。诊可十全。不失人情。  故诊之或视息视意。故不失条理。道甚明察。故能长久。不知此道。失经绝理。亡言妄期。此谓失道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202861,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '19、是以诊有大方。坐起有常。出入有行。以转神明。必清必净。上观下观。司八正邪。别五中部。按脉动静。循尺滑涩。寒温之意。视其大小。合之病能。逆从以得。复知病名。诊可十全。不失人情。 故诊之或视息视意。故不失条理。道甚明察。故能长久。不知此道。失经绝理。亡言妄期。此谓失道。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0GeAp863LNO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WGMa4GNW1UM', 4, '{"title":"第20202862条・解精微论篇第八十一","description":"<p>1、黄帝在明堂。雷公请曰：臣授业传之。行教以经论。从容形法。阴阳刺灸。汤药所滋。行治有贤不肖。未必能十全。若先言悲哀喜怒。燥湿寒暑。阴阳妇女。请问其所以然者。卑贱富贵。人之形体所从。群下通使。临事以适道术。谨闻命矣。请问有（免免=上下）愚仆漏之问。不在经者。欲闻其状。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202862,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '1、黄帝在明堂。雷公请曰：臣授业传之。行教以经论。从容形法。阴阳刺灸。汤药所滋。行治有贤不肖。未必能十全。若先言悲哀喜怒。燥湿寒暑。阴阳妇女。请问其所以然者。卑贱富贵。人之形体所从。群下通使。临事以适道术。谨闻命矣。请问有（免免=上下）愚仆漏之问。不在经者。欲闻其状。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1zy0ZyhB7hB', 4, '{"title":"第20202863条・解精微论篇第八十一","description":"<p>2、帝曰：大矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202863,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2、帝曰：大矣。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tCuqnHUkFwc', 4, '{"title":"第20202864条・解精微论篇第八十一","description":"<p>3、公请问：哭泣而泪不出者。若出而少涕。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202864,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '3、公请问：哭泣而泪不出者。若出而少涕。其故何也？', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z8dnxRboEIU', 4, '{"title":"第20202865条・解精微论篇第八十一","description":"<p>4、帝曰：在经有也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202865,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '4、帝曰：在经有也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jRFHel6Ty7h', 4, '{"title":"第20202866条・解精微论篇第八十一","description":"<p>5、复问：不知水所从生。涕所从出也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202866,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '5、复问：不知水所从生。涕所从出也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MqtsV0UF61P', 4, '{"title":"第20202867条・解精微论篇第八十一","description":"<p>6、帝曰：若问此者。无益于治也。工之所知。道之所生也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202867,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '6、帝曰：若问此者。无益于治也。工之所知。道之所生也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lrFBaGAkn20', 4, '{"title":"第20202868条・解精微论篇第八十一","description":"<p>7、夫心者。五藏之专精也。目者其窍也。华色者其荣也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202868,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '7、夫心者。五藏之专精也。目者其窍也。华色者其荣也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oRI6H6xFjun', 4, '{"title":"第20202869条・解精微论篇第八十一","description":"<p>8、是以人有德也。则气和于目。有亡。忧知于色。是以悲哀则泣下。泣下水所由生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202869,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '8、是以人有德也。则气和于目。有亡。忧知于色。是以悲哀则泣下。泣下水所由生。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Je1n26dSjo5', 4, '{"title":"第20202870条・解精微论篇第八十一","description":"<p>9、水宗者积水也。积水者至阴也。至阴者肾之精也。宗精之水所以不出者。是精持之也。辅之裹之。故水不行也。夫水之精为志。火之精为神。水火相感。神志俱悲。是以目之水生也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202870,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '9、水宗者积水也。积水者至阴也。至阴者肾之精也。宗精之水所以不出者。是精持之也。辅之裹之。故水不行也。夫水之精为志。火之精为神。水火相感。神志俱悲。是以目之水生也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JnKKyLQoVR6', 4, '{"title":"第20202871条・解精微论篇第八十一","description":"<p>10、故谚言曰：心悲名曰志悲。志与心精。共凑于目也。是以俱悲则神气传于心精。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202871,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '10、故谚言曰：心悲名曰志悲。志与心精。共凑于目也。是以俱悲则神气传于心精。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Ag60IangmS', 4, '{"title":"第20202872条・解精微论篇第八十一","description":"<p>11、上不传于志而志独悲。故泣出也。泣涕者脑也。脑者阴也。髓者骨之充也。故脑渗为涕。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202872,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '11、上不传于志而志独悲。故泣出也。泣涕者脑也。脑者阴也。髓者骨之充也。故脑渗为涕。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XPXuLChWRzK', 4, '{"title":"第20202873条・解精微论篇第八十一","description":"<p>12、志者骨之主也。是以水流而涕从之者。其行类也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202873,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '12、志者骨之主也。是以水流而涕从之者。其行类也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('htnnTOrQZ6o', 4, '{"title":"第20202874条・解精微论篇第八十一","description":"<p>13、夫涕之与泣者。譬如人之兄弟。急则俱死。生则俱生。其志以早悲。是以涕泣俱出而横行也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202874,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '13、夫涕之与泣者。譬如人之兄弟。急则俱死。生则俱生。其志以早悲。是以涕泣俱出而横行也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e10QqMLAFBY', 4, '{"title":"第20202875条・解精微论篇第八十一","description":"<p>14、夫人涕泣俱出而相从者。所属之类也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202875,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '14、夫人涕泣俱出而相从者。所属之类也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3U5PdQlu3re', 4, '{"title":"第20202876条・解精微论篇第八十一","description":"<p>15、雷公曰：大矣。请问人哭泣而泪不出。若出而少。涕不从之何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202876,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '15、雷公曰：大矣。请问人哭泣而泪不出。若出而少。涕不从之何也？', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('18j6QHGjbhm', 4, '{"title":"第20202877条・解精微论篇第八十一","description":"<p>16、帝曰： 夫泣不出者。哭不悲也。不泣者。神不慈也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202877,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '16、帝曰： 夫泣不出者。哭不悲也。不泣者。神不慈也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LG6O0mNKJLn', 4, '{"title":"第20202878条・解精微论篇第八十一","description":"<p>17、神不慈则志不悲。阴阳相持。泣安能独来。夫志悲者惋。惋则冲阴。冲阴则志去目。志去则神不守精。精神去目。涕泣出也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202878,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '17、神不慈则志不悲。阴阳相持。泣安能独来。夫志悲者惋。惋则冲阴。冲阴则志去目。志去则神不守精。精神去目。涕泣出也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PpX6STCDLeu', 4, '{"title":"第20202879条・解精微论篇第八十一","description":"<p>18、且子独不诵不念夫经言乎。厥则目无所见。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202879,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '18、且子独不诵不念夫经言乎。厥则目无所见。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mM7ZEcxox4a', 4, '{"title":"第20202880条・解精微论篇第八十一","description":"<p>19、夫人厥。则阳气并于上。阴气并于下。阳并于上。则火独光也。阴并于下。则足寒。足寒则胀也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202880,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '19、夫人厥。则阳气并于上。阴气并于下。阳并于上。则火独光也。阴并于下。则足寒。足寒则胀也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H1ml5tmlQqS', 4, '{"title":"第20202881条・解精微论篇第八十一","description":"<p>20、夫一水不胜五火。故目盲。是以冲风。泣下而不止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202881,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '20、夫一水不胜五火。故目盲。是以冲风。泣下而不止。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TIN0EWWwx06', 4, '{"title":"第20202882条・解精微论篇第八十一","description":"<p>21、夫风之中目也。阳气内守于精。是火气燔目。故见风则泣下也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202882,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '21、夫风之中目也。阳气内守于精。是火气燔目。故见风则泣下也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N1ttuZtym0j', 4, '{"title":"第20202883条・解精微论篇第八十一","description":"<p>22、有以比之。 夫火疾风生乃能雨。此之类也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202883,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '2024-09-26T13:53:19.000Z', '22、有以比之。 夫火疾风生乃能雨。此之类也。', '2024-09-26T13:53:19.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'Rz6DTMvFbVe');
